import { fireEvent, screen } from "@testing-library/react";
import type { ComponentProps } from "react";
import { describe, expect, it, vi } from "vitest";
import { renderWithProviders } from "../../../tests/utils";
import { ConversationEventType, type ConversationEvent } from "../../../types";
import { ToolRunLogRow } from "./ToolRunLogRow";

const baseEvent: ConversationEvent = {
  __typename: "ConversationEvent",
  id: "1",
  conversationEventType: ConversationEventType.McpToolExecuted,
  name: "event_name",
  actionText: "",
  flowId: "",
  slotValue: null,
  stepId: "",
  timestamp: new Date().toISOString(),
  originalTimestamp: 0,
  metadata: {
    tool_name: "my_tool",
    parseData: {},
  },
};

function CalmRow(
  props: { event: ConversationEvent } & Partial<ComponentProps<typeof ToolRunLogRow>>,
) {
  const { event, isSelected = false, ...rest } = props;
  return (
    <ToolRunLogRow event={event} isSelected={isSelected} prefix="Tool " suffix=" used" {...rest} />
  );
}

describe("ToolRunLogRow", () => {
  describe("tool name display", () => {
    it("uses tool_name from metadata", () => {
      renderWithProviders(<CalmRow event={baseEvent} />);

      expect(screen.getByText("my_tool")).toBeInTheDocument();
    });

    it("falls back to event.name when metadata.tool_name is absent", () => {
      const event: ConversationEvent = {
        ...baseEvent,
        metadata: { parseData: {} },
      };

      renderWithProviders(<CalmRow event={event} />);

      expect(screen.getByText("event_name")).toBeInTheDocument();
    });
  });

  describe("terminology", () => {
    it("renders the given prefix and suffix", () => {
      renderWithProviders(<CalmRow event={baseEvent} />);

      expect(screen.getByText(/used/)).toBeInTheDocument();
      expect(screen.queryByText(/Tool call:/)).not.toBeInTheDocument();
    });
  });

  describe("execution status", () => {
    it("shows no error dot when tool_is_error is false", () => {
      const event: ConversationEvent = {
        ...baseEvent,
        metadata: { ...baseEvent.metadata, tool_is_error: false },
      };

      renderWithProviders(<CalmRow event={event} />);

      expect(screen.queryByTestId("error-dot")).not.toBeInTheDocument();
    });

    it("shows no error dot when tool_is_error is absent", () => {
      renderWithProviders(<CalmRow event={baseEvent} />);

      expect(screen.queryByTestId("error-dot")).not.toBeInTheDocument();
    });

    it("shows an error dot when tool_is_error is true", () => {
      const event: ConversationEvent = {
        ...baseEvent,
        metadata: { ...baseEvent.metadata, tool_is_error: true },
      };

      renderWithProviders(<CalmRow event={event} />);

      expect(screen.getByTestId("error-dot")).toBeInTheDocument();
    });
  });

  describe("interaction", () => {
    it("calls onClick when clicked", () => {
      const onClick = vi.fn();

      renderWithProviders(<CalmRow event={baseEvent} onClick={onClick} />);

      fireEvent.click(screen.getByRole("button"));
      expect(onClick).toHaveBeenCalledTimes(1);
    });

    it("calls onKeyDown when a key is pressed", () => {
      const onKeyDown = vi.fn();

      renderWithProviders(<CalmRow event={baseEvent} onKeyDown={onKeyDown} />);

      fireEvent.keyDown(screen.getByRole("button"), { key: "Enter" });
      expect(onKeyDown).toHaveBeenCalledTimes(1);
    });
  });

  describe("hover actions", () => {
    const actions = [{ icon: {} as never, label: "Copy", action: vi.fn() }];

    it("does not show action button when not hovered", () => {
      renderWithProviders(<CalmRow event={baseEvent} conversationEventActions={actions} />);

      expect(screen.queryByText("Copy")).not.toBeInTheDocument();
    });

    it("shows action button on hover", () => {
      renderWithProviders(<CalmRow event={baseEvent} conversationEventActions={actions} />);

      fireEvent.mouseEnter(screen.getByRole("button"));
      expect(screen.getByText("Copy")).toBeInTheDocument();
    });

    it("hides action button after mouse leaves", () => {
      renderWithProviders(<CalmRow event={baseEvent} conversationEventActions={actions} />);

      const container = screen.getByRole("button");
      fireEvent.mouseEnter(container);
      fireEvent.mouseLeave(container);
      expect(screen.queryByText("Copy")).not.toBeInTheDocument();
    });
  });
});
